function makeLabels(total) {
  const parts = [];
  let remaining = total;
  while (remaining > 0) {
    let take = Math.min(63, remaining);
    if (remaining - take === 1) take -= 1;
    parts.push("d".repeat(take));
    remaining -= take;
    if (remaining > 0) remaining -= 1;
  }
  return parts.join(".");
}
